<script setup lang="ts">
import { onMounted, reactive, ref, watch } from "vue"; import { Eye, FileWarning, Trash2 } from "@lucide/vue"; import { useRoute } from "vue-router"; import { toast } from "vue-sonner"; import { adminApi } from "../api/admin.api"; import type { ErrorLogItem } from "../types"; import StatePanel from "../components/StatePanel.vue";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog"; import { Badge } from "@/components/ui/badge"; import { Button } from "@/components/ui/button"; import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"; import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"; import { Pagination, PaginationContent, PaginationEllipsis, PaginationItem, PaginationNext, PaginationPrevious } from "@/components/ui/pagination"; import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";  import { Skeleton } from "@/components/ui/skeleton"; import { Spinner } from "@/components/ui/spinner"; import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
const types=[{value:"all",label:"Все типы"},{value:"ai",label:"AI"},{value:"telegram",label:"Telegram"},{value:"system",label:"Система"}],services=[{value:"all",label:"Все сервисы"},{value:"whisper",label:"Whisper"},{value:"llm",label:"LLM"},{value:"tts",label:"TTS"},{value:"telegram",label:"Telegram"},{value:"scheduler",label:"Планировщик"},{value:"general",label:"Общее"}];
const route=useRoute();const correlationId=ref(typeof route.query.correlationId==="string"?route.query.correlationId:undefined);
const logs=ref<ErrorLogItem[]>([]),loading=ref(true),error=ref(false),clearing=ref(false),selected=ref<ErrorLogItem|null>(null),detailOpen=ref(false),clearOpen=ref(false);const filters=reactive({type:"all",service:"all"});const pagination=reactive({page:1,limit:50,total:0});const formatDate=(v:string)=>new Date(v).toLocaleString("ru-RU");let requestSequence=0;
async function load(page=pagination.page){const requestId=++requestSequence;loading.value=true;error.value=false;try{const r=await adminApi.getErrorLogs(page,pagination.limit,filters.type==="all"?undefined:filters.type,filters.service==="all"?undefined:filters.service,correlationId.value);if(requestId!==requestSequence)return;logs.value=r.data;Object.assign(pagination,{page:r.page,limit:r.limit,total:r.total});}catch{if(requestId===requestSequence)error.value=true;}finally{if(requestId===requestSequence)loading.value=false;}}
function show(log:ErrorLogItem){selected.value=log;detailOpen.value=true;} async function clearOld(){clearing.value=true;try{const r=await adminApi.clearOldErrorLogs(30);toast.success(`Удалено записей: ${r.deleted}`);clearOpen.value=false;await load(1);}catch{toast.error("Не удалось удалить записи");}finally{clearing.value=false;}} watch(filters,()=>load(1));watch(()=>route.query.correlationId,(value)=>{correlationId.value=typeof value==="string"?value:undefined;void load(1);});onMounted(()=>load(1));
</script>
<template><section class="flex flex-col gap-6"><header class="page-header"><div><p class="eyebrow">Мониторинг</p><h1>Логи ошибок</h1><p>Диагностика сервисов и системных сбоев.</p></div><div class="header-actions"><Select v-model="filters.type"><SelectTrigger aria-label="Фильтр по типу"><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem v-for="i in types" :key="i.value" :value="i.value">{{i.label}}</SelectItem></SelectGroup></SelectContent></Select><Select v-model="filters.service"><SelectTrigger aria-label="Фильтр по сервису"><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem v-for="i in services" :key="i.value" :value="i.value">{{i.label}}</SelectItem></SelectGroup></SelectContent></Select><Button variant="destructive" :disabled="clearing||loading" @click="clearOpen=true"><Trash2 data-icon="inline-start"/>Очистить старые</Button></div></header>
<StatePanel v-if="error&&!loading" title="Не удалось загрузить логи" retry-label="Повторить" @retry="load()"/><div v-else class="overflow-hidden rounded-xl border bg-card text-card-foreground"><div class="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Дата</TableHead><TableHead>Тип</TableHead><TableHead>Сервис</TableHead><TableHead>Сообщение</TableHead><TableHead>User ID</TableHead><TableHead><span class="sr-only">Детали</span></TableHead></TableRow></TableHeader><TableBody v-if="loading"><TableRow v-for="i in 6" :key="i"><TableCell v-for="j in 6" :key="j"><Skeleton class="h-5 w-full"/></TableCell></TableRow></TableBody><TableBody v-else><TableRow v-for="row in logs" :key="row.id"><TableCell class="whitespace-nowrap">{{formatDate(row.createdAt)}}</TableCell><TableCell><Badge :variant="row.type==='system'?'destructive':'outline'">{{row.type.toUpperCase()}}</Badge></TableCell><TableCell><Badge variant="secondary">{{row.service}}</Badge></TableCell><TableCell class="max-w-md truncate">{{row.message}}</TableCell><TableCell>{{row.userId||"—"}}</TableCell><TableCell><Button variant="ghost" size="icon-sm" aria-label="Посмотреть детали" @click="show(row)"><Eye/></Button></TableCell></TableRow></TableBody></Table><Empty v-if="!loading&&!logs.length"><EmptyHeader><EmptyMedia variant="icon"><FileWarning/></EmptyMedia><EmptyTitle>Логов нет</EmptyTitle><EmptyDescription>По выбранным фильтрам записи отсутствуют.</EmptyDescription></EmptyHeader></Empty></div><Pagination v-if="pagination.total>pagination.limit" :page="pagination.page" :total="pagination.total" :items-per-page="pagination.limit" :sibling-count="1" class="border-t p-4" @update:page="load"><PaginationContent v-slot="{items}"><PaginationPrevious/><template v-for="(item,itemIndex) in items" :key="item.type==='page'?item.value:'ellipsis-'+itemIndex"><PaginationItem v-if="item.type==='page'" :value="item.value" :is-active="item.value===pagination.page">{{item.value}}</PaginationItem><PaginationEllipsis v-if="item.type==='ellipsis'" :index="itemIndex"/></template><PaginationNext/></PaginationContent></Pagination></div>
<Dialog v-model:open="detailOpen"><DialogContent class="max-h-[90vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Детали ошибки</DialogTitle><DialogDescription>Техническая информация для диагностики.</DialogDescription></DialogHeader><div v-if="selected" class="log-detail"><dl><div><dt>Дата</dt><dd>{{formatDate(selected.createdAt)}}</dd></div><div><dt>Тип</dt><dd><Badge :variant="selected.type==='system'?'destructive':'outline'">{{selected.type.toUpperCase()}}</Badge></dd></div><div><dt>Сервис</dt><dd>{{selected.service}}</dd></div><div v-if="selected.userId"><dt>User ID</dt><dd><code>{{selected.userId}}</code></dd></div></dl><section><strong>Сообщение</strong><pre class="code-block code-block--light">{{selected.message}}</pre></section><section v-if="selected.stack"><strong>Stack trace</strong><pre class="code-block">{{selected.stack}}</pre></section><section v-if="selected.metadata!=null"><strong>Metadata</strong><pre class="code-block code-block--light">{{JSON.stringify(selected.metadata,null,2)}}</pre></section></div></DialogContent></Dialog>
<AlertDialog v-bind:open="clearOpen" @update:open="!clearing && (clearOpen = $event)"><AlertDialogContent @escape-key-down="clearing&&$event.preventDefault()" @pointer-down-outside="clearing&&$event.preventDefault()"><AlertDialogHeader><AlertDialogTitle>Очистить старые логи?</AlertDialogTitle><AlertDialogDescription>Будут удалены все логи старше 30 дней. Это действие нельзя отменить.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel :disabled="clearing">Отмена</AlertDialogCancel><AlertDialogAction variant="destructive" :disabled="clearing" @click.prevent="clearOld"><Spinner v-if="clearing" data-icon="inline-start"/>Удалить</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
</section></template>
